import {calendarMonth,calendarEntries,validCalendarDate} from './calendar-state.js';
import {newId} from './cloud.js?v=6';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createCalendarUI({context,modal,save,cloud,toast,handlers,journal,today}){
 let selected=today(),month=selected.slice(0,7),draft=null,busy=false,dirty=false;
 const css=document.createElement('link');css.rel='stylesheet';css.href='/calendar.css';document.head.append(css);
 const button=(action,label,attr='')=>'<button type="button" data-cal="'+action+'" '+attr+'>'+label+'</button>';
 const entries=date=>{const c=context();return calendarEntries(c.state.notes,date,c.actor,c.paired)};
 function form(){if(!draft)return '';const unpaired=!context().paired;return '<form id="calendar-form"><label for="calendar-title" class="sr-only">记事</label><input id="calendar-title" name="title" maxlength="80" required placeholder="记一件事…" value="'+esc(draft.title)+'"><label for="calendar-body" class="sr-only">补充</label><textarea id="calendar-body" name="body" maxlength="2000" placeholder="补充一点（可不填）">'+esc(draft.body)+'</textarea><div class="calendar-edit-row"><input type="date" aria-label="记事日期" name="date" min="1000-01-01" max="9999-12-31" required value="'+draft.date+'"><label><input name="shared" type="checkbox" '+(draft.shared?'checked ':'')+(unpaired?'disabled':'')+'>对方可见</label></div>'+(unpaired?'<small>配对后可分享</small>':'')+'<div class="calendar-actions">'+button('cancel','取消')+'<button type="submit" class="primary">保存</button></div><p class="calendar-error" role="status"></p></form>'}
 function draw(){const {year,month:m,offset,days}=calendarMonth(month+'-01'),c=context(),list=entries(selected);let cells=Array(offset).fill('<span></span>');for(let day=1;day<=days;day++){const date=month+'-'+String(day).padStart(2,'0'),marks=entries(date);cells.push(button('day','<span>'+day+'</span>'+(marks.length?'<i class="'+(marks.some(e=>e.shared)?'shared':'')+'"></i>':''),'data-date="'+date+'" aria-label="'+date+(marks.length?' 有记事':'')+'" aria-pressed="'+(date===selected)+'" '+(date===today()?'aria-current="date"':'')))}
 modal('calendar','','日历','<div class="calendar"><div class="calendar-top">'+button('back','手账')+'<strong>'+year+' 年 '+m+' 月</strong><div>'+button('prev','‹','aria-label="上个月" '+(month==='1000-01'?'disabled':''))+button('next','›','aria-label="下个月" '+(month==='9999-12'?'disabled':''))+'</div></div><div class="calendar-week">'+['一','二','三','四','五','六','日'].map(d=>'<span>'+d+'</span>').join('')+'</div><div class="calendar-days">'+cells.join('')+'</div><div class="calendar-day-heading"><strong>'+Number(selected.slice(5,7))+' 月 '+Number(selected.slice(8))+' 日</strong>'+button('today','今天')+button('new','＋ 记事')+'</div><div class="calendar-notes">'+list.map(n=>'<article><div><b>'+esc(n.title)+'</b><small>'+esc(n.actor===c.actor?(n.shared?'对方可见':'仅自己'):c.names[n.actor]+' · 分享')+(n.kind==='anniversary'?' · 纪念日':'')+'</small></div>'+(n.body?'<p>'+esc(n.body)+'</p>':'')+(n.actor===c.actor&&n.kind==='calendar'?button('edit','编辑','data-id="'+n.id+'"')+button('delete','删除','data-id="'+n.id+'"'):'')+'</article>').join('')+(!list.length&&!draft?'<p class="calendar-empty">这一天，留一点空白。</p>':'')+'</div>'+form()+'</div>');if(busy)document.querySelectorAll('.calendar button,.calendar input,.calendar textarea').forEach(e=>e.disabled=true)}
 function guard(){return !draft||!dirty||confirm('放弃尚未保存的内容？')}
 function show(){selected=today();month=selected.slice(0,7);draft=null;dirty=false;draw()}
 async function persist(){save();return !cloud||await cloud.flush()}
 document.querySelector('#panel-body').addEventListener('click',async e=>{const b=e.target.closest('[data-cal]');if(!b||b.disabled||busy)return;const a=b.dataset.cal,c=context();if(['back','day','prev','next','today','new','edit'].includes(a)&&!guard())return;
 dirty=false;if(a==='back'){draft=null;journal();return}if(a==='day'){selected=b.dataset.date;draft=null}if(a==='prev'||a==='next'){const d=new Date(month+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+(a==='next'?1:-1));selected=d.toISOString().slice(0,10);month=selected.slice(0,7);draft=null}if(a==='today'){selected=today();month=selected.slice(0,7);draft=null}if(a==='new')draft={title:'',body:'',date:selected,shared:false};if(a==='cancel'){if(!guard())return;draft=null}if(a==='edit'){const n=c.state.notes.find(n=>n.id===b.dataset.id&&n.actor===c.actor&&n.kind==='calendar');if(n)draft={...n}}
 if(a==='delete'){const n=c.state.notes.find(n=>n.id===b.dataset.id&&n.actor===c.actor&&n.kind==='calendar');if(!n||!confirm('删除这条记事？'))return;busy=true;draw();c.state.notes=c.state.notes.filter(x=>x!==n);const ok=await persist();busy=false;if(ok)toast('已删除');if(context().panel!=='calendar')return;}draw();
 });
 document.querySelector('#panel-body').addEventListener('input',e=>{if(!draft||!e.target.closest('#calendar-form'))return;const f=e.target;dirty=true;draft[f.name]=f.type==='checkbox'?f.checked:f.value});
 document.querySelector('#panel-body').addEventListener('submit',async e=>{if(e.target.id!=='calendar-form'||busy||!draft)return;e.preventDefault();const c=context(),title=draft.title.trim();if(!title||!validCalendarDate(draft.date))return;busy=true;const d={...draft,title,body:draft.body.trim(),shared:c.paired&&!!draft.shared};if(d.id){const n=c.state.notes.find(n=>n.id===d.id&&n.actor===c.actor&&n.kind==='calendar');if(!n){busy=false;return}Object.assign(n,{title:d.title,body:d.body,date:d.date,shared:d.shared})}else c.state.notes.unshift({id:newId(),actor:c.actor,world:c.actor,title:d.title,body:d.body,date:d.date,kind:'calendar',shared:d.shared,repeat:false,created:Date.now(),weather:'',comments:[]});draw();const ok=await persist();busy=false;if(ok){selected=d.date;month=selected.slice(0,7);draft=null;dirty=false;toast('已保存')}if(ok&&context().panel==='calendar')draw();});
 handlers.calendar=show;
 return {open:show,refresh(){if(context().panel==='calendar'&&!draft&&!busy)draw()}};
}
